(694822, 72822, 4008, '<td valign="top">An absolutely beautiful image of this piece of architectural art. Well composed, nice soft contrast. But still very much a recording of reality, not an abstraction of it in my opinion.</td>', 'An absolutely beautiful image of this piece of architectural art. Well composed, nice soft contrast. But still very much a recording of reality, not an abstraction of it in my opinion.', '2004-05-03 07:29:16.000000', NULL, 1),
(694824, 73988, 4008, '<td valign="top">I really like the minimalistic approach. Simple, strong image. A bit too depressing atmosphere for me to put on a wall at home.</td>', 'I really like the minimalistic approach. Simple, strong image. A bit too depressing atmosphere for me to put on a wall at home.', '2004-05-03 07:31:53.000000', NULL, 1),
(694831, 73848, 1829, '<td valign="top">Excellent colour, texture and tone in your image.  An excellent form of abstract!!</td>', 'Excellent colour, texture and tone in your image.  An excellent form of abstract!!', '2004-05-03 07:45:57.000000', NULL, 1),
(694832, 73821, 20204, '<td valign="top">This immediately struck me as being very creative.  I like the green with the blue, I love the flipped image, and the detail seems to be excellent.  Great picture!</td>', 'This immediately struck me as being very creative.  I like the green with the blue, I love the flipped image, and the detail seems to be excellent.  Great picture!', '2004-05-03 07:46:12.000000', NULL, 1),
(694836, 73227, 1829, '<td valign="top">Your photograph is a perfect example of abstract.  It''s colours, tone of lighting are just excellent as well.  The black hole also gives me the impression as to wonder what''s beyond there, kinda like a tunnel.  Certainly a 10 for your picture and for a job well done.</td>', 'Your photograph is a perfect example of abstract.  It''s colours, tone of lighting are just excellent as well.  The black hole also gives me the impression as to wonder what''s beyond there, kinda like a tunnel.  Certainly a 10 for your picture and for a job well done.', '2004-05-03 07:49:54.000000', NULL, 1),
(694838, 73652, 1829, '<td valign="top">WOW what a great catch!!!  Love the ripples in the water and the way the blues mix together....excellent job!</td>', 'WOW what a great catch!!!  Love the ripples in the water and the way the blues mix together....excellent job!', '2004-05-03 07:51:42.000000', NULL, 1),
