(694888, 73883, 8643, '<td valign="top">There is something very appealing about this - well spotted and a lovely crisp photo.  Must ahve taken some care to get it square, an important element to contrast with the distortions.  I also like the vertical asymmetry contrasting with the horizontal symmetry.  This ought to be the winner - 10</td>', 'There is something very appealing about this - well spotted and a lovely crisp photo.  Must ahve taken some care to get it square, an important element to contrast with the distortions.  I also like the vertical asymmetry contrasting with the horizontal symmetry.  This ought to be the winner - 10', '2004-05-03 08:56:21.000000', NULL, 1),
(694891, 73190, 19040, '<td valign="top">Cool. What is it and how did you do it?</td>', 'Cool. What is it and how did you do it?', '2004-05-03 08:56:59.000000', NULL, 1),
