INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(695438, 73386, 15920, '<td valign="top">Contrary to most voters, I am OK with rust in the Abstract challenge.  On this particular image, I think the focus region would have made more of an impact if it was started and ended a little more than an inch to the right.  As is, this still convinces me that a blue ribbon is not going to happen for me in the rust challenge,  -8</td>', 'Contrary to most voters, I am OK with rust in the Abstract challenge.  On this particular image, I think the focus region would have made more of an impact if it was started and ended a little more than an inch to the right.  As is, this still convinces me that a blue ribbon is not going to happen for me in the rust challenge,  -8', '2004-05-03 15:11:38.000000', NULL, 1),
(695445, 73872, 16004, '<td valign="top">Clue in the title?  A big rat, perhaps? (or at least it''s habitat).  Only a guess.  It''s a good shot, though the slight flaw in the bottom right could have been gently cloned out (kind of upsets the symmetry you have going on).  no idea what it is though...</td>', 'Clue in the title?  A big rat, perhaps? (or at least it''s habitat).  Only a guess.  It''s a good shot, though the slight flaw in the bottom right could have been gently cloned out (kind of upsets the symmetry you have going on).  no idea what it is though...', '2004-05-03 15:17:24.000000', NULL, 1),
(695450, 73947, 15920, '<td valign="top">My daughter''s favorite color scheme, so it must be good.    Whatever this is, a little sharper focus would have gotten a 9 rather than the 7 I am giving it.  Despite the complaints, this is pleasing to the eye.</td>', 'My daughter''s favorite color scheme, so it must be good.    Whatever this is, a little sharper focus would have gotten a 9 rather than the 7 I am giving it.  Despite the complaints, this is pleasing to the eye.', '2004-05-03 15:23:38.000000', NULL, 1),
(695461, 74004, 15920, '<td valign="top">This is pretty cool.  I can''t see it on my wall if it is this bright, but I can see it on my son''s. -7</td>', 'This is pretty cool.  I can''t see it on my wall if it is this bright, but I can see it on my son''s. -7', '2004-05-03 15:28:41.000000', NULL, 1),
(695462, 73143, 7322, '<td valign="top">This is really nice. Nice sharp image, good deliniation of line, form, and color. Kudos on meeting the challenge so well.</td>', 'This is really nice. Nice sharp image, good deliniation of line, form, and color. Kudos on meeting the challenge so well.', '2004-05-03 15:29:11.000000', NULL, 1),
(695464, 73872, 15920, '<td valign="top">"Brain Impulse Galvanoscope Record And Transfer"?  I thought it was an exceptionally well photographed ''slinky''.  Regardless of what it is, this is very well done.  -8</td>', '"Brain Impulse Galvanoscope Record And Transfer"?  I thought it was an exceptionally well photographed ''slinky''.  Regardless of what it is, this is very well done.  -8', '2004-05-03 15:31:09.000000', NULL, 1),
(695466, 73817, 7322, '<td valign="top">The dead centered white paint splotch isn''t doing much for me. Perhaps if you had framed it so it was off center and coming from a corner of the frame. It might have been interesting, for instance, to have the white lines radiating from the top left corner of the frame.</td>', 'The dead centered white paint splotch isn''t doing much for me. Perhaps if you had framed it so it was off center and coming from a corner of the frame. It might have been interesting, for instance, to have the white lines radiating from the top left corner of the frame.', '2004-05-03 15:32:36.000000', NULL, 1),
(695467, 73809, 4008, '<td valign="top">I like it how the blue reflection varies from top to bottom of the image.</td>', 'I like it how the blue reflection varies from top to bottom of the image.', '2004-05-03 15:32:36.000000', NULL, 1),
(695470, 73188, 4008, '<td valign="top">If you would have gone closer it would have been more of an abstract.</td>', 'If you would have gone closer it would have been more of an abstract.', '2004-05-03 15:33:19.000000', NULL, 1),
(695471, 73932, 7322, '<td valign="top">This is a nice clean abstract image. Nice form and good contrast. It doesn''t wow me but it works.</td>', 'This is a nice clean abstract image. Nice form and good contrast. It doesn''t wow me but it works.', '2004-05-03 15:33:43.000000', NULL, 1),
(695473, 73989, 4008, '<td valign="top">If you would have gone closer it would have been more of an abstract.</td>', 'If you would have gone closer it would have been more of an abstract.', '2004-05-03 15:34:17.000000', NULL, 1),
(695476, 73932, 4008, '<td valign="top">Crop away some more, especially the bottom left corner, and it becomes an abstract.</td>', 'Crop away some more, especially the bottom left corner, and it becomes an abstract.', '2004-05-03 15:34:57.000000', NULL, 1),
(695478, 73199, 4008, '<td valign="top">If you would have gone closer it would have been more of an abstract.</td>', 'If you would have gone closer it would have been more of an abstract.', '2004-05-03 15:35:22.000000', NULL, 1),
(695479, 73959, 7322, '<td valign="top">I like that you used an infinite depth of field (at least it seems that way) to really flatten the shape of the pasta scoop to an abstract form. Good use of bold, contrasting color and pattern. It doesn''t wow me but it works.</td>', 'I like that you used an infinite depth of field (at least it seems that way) to really flatten the shape of the pasta scoop to an abstract form. Good use of bold, contrasting color and pattern. It doesn''t wow me but it works.', '2004-05-03 15:36:37.000000', NULL, 1),
(695483, 74002, 4008, '<td valign="top">I like the colors and it is a real abstract. Only the lower left corner is distracting.</td>', 'I like the colors and it is a real abstract. Only the lower left corner is distracting.', '2004-05-03 15:37:33.000000', NULL, 1),
(695484, 73461, 7322, '<td valign="top">The black background is a bit too foggy and the colors aren''t quite bold enough for this to be really striking. Nice use of the image plane and you''ve kept it simple. Doesn''t wow me but it''s getting there.</td>', 'The black background is a bit too foggy and the colors aren''t quite bold enough for this to be really striking. Nice use of the image plane and you''ve kept it simple. Doesn''t wow me but it''s getting there.', '2004-05-03 15:37:53.000000', NULL, 1),
(695486, 73902, 7322, '<td valign="top">I like the interesting texture and the color in this photo. It could be a bit sharper in focus. Nice effort.</td>', 'I like the interesting texture and the color in this photo. It could be a bit sharper in focus. Nice effort.', '2004-05-03 15:38:58.000000', NULL, 1),
(695492, 73802, 7322, '<td valign="top">Ordinarily I would critique the blurred foreground but in this case the pale blue-grey blends invisibly into the white background in a pleasing way. The soft focus and light value contrasts nicely with the sharp focus and dark values.</td>', 'Ordinarily I would critique the blurred foreground but in this case the pale blue-grey blends invisibly into the white background in a pleasing way. The soft focus and light value contrasts nicely with the sharp focus and dark values.', '2004-05-03 15:41:19.000000', NULL, 1),
(695494, 73512, 19780, '<td valign="top">Beautiful colors. I love the lines and compositiong and how the vertical streaking aids the composition.</td>', 'Beautiful colors. I love the lines and compositiong and how the vertical streaking aids the composition.', '2004-05-03 15:41:35.000000', NULL, 1),
(695495, 74006, 4008, '<td valign="top">very good, pleasant image with the happy atmosphere of spring, real abstract.</td>', 'very good, pleasant image with the happy atmosphere of spring, real abstract.', '2004-05-03 15:42:10.000000', NULL, 1),
(695498, 73991, 4008, '<td valign="top">great soft flowing lines, attractive warm image, real abstract</td>', 'great soft flowing lines, attractive warm image, real abstract', '2004-05-03 15:43:41.000000', NULL, 1),
(695499, 73852, 4008, '<td valign="top">just reality, no abstract, you might want to read the challenge description again.</td>', 'just reality, no abstract, you might want to read the challenge description again.', '2004-05-03 15:45:00.000000', NULL, 1),
(695501, 73538, 18950, '<td valign="top">I like it, great colors.</td>', 'I like it, great colors.', '2004-05-03 15:45:48.000000', NULL, 1),
(695502, 73403, 4008, '<td valign="top">just reality, no abstract in the definition of this challenge</td>', 'just reality, no abstract in the definition of this challenge', '2004-05-03 15:45:51.000000', NULL, 1),
(695505, 72654, 19780, '<td valign="top">Wonderful abstract - I have no clue what this is. I love the colors and the texture of the fringy stuff. The lighting is very interesting and aids in a compelling composition.</td>', 'Wonderful abstract - I have no clue what this is. I love the colors and the texture of the fringy stuff. The lighting is very interesting and aids in a compelling composition.', '2004-05-03 15:46:36.000000', NULL, 1),
(695506, 74005, 19608, '<td valign="top">It is an interesting idea - makes one ponder.</td>', 'It is an interesting idea - makes one ponder.', '2004-05-03 15:46:46.000000', NULL, 1),
(695507, 73970, 19780, '<td valign="top">Looks like bananas, but I love the colors and the irregular nature of the curves and variations in the color.</td>', 'Looks like bananas, but I love the colors and the irregular nature of the curves and variations in the color.', '2004-05-03 15:47:31.000000', NULL, 1),
(695509, 73925, 19608, '<td valign="top">Colors are very nice - ripples in the "water" add a nice touch.</td>', 'Colors are very nice - ripples in the "water" add a nice touch.', '2004-05-03 15:48:04.000000', NULL, 1),
(695511, 72822, 19608, '<td valign="top">One of my favorites in this challenge.  I am sure you will get some comments about it not being abstract enough, but ignore them.  This works!  Great lines, colors, composition.  Very well done indeed; I predict a VERY high finish.</td>', 'One of my favorites in this challenge.  I am sure you will get some comments about it not being abstract enough, but ignore them.  This works!  Great lines, colors, composition.  Very well done indeed; I predict a VERY high finish.', '2004-05-03 15:50:19.000000', NULL, 1),
(695513, 72443, 19780, '<td valign="top">Lovely colors and lighting. I''m not sure about the darker lump at the top - I''d find the composition a little more pleasing with a crop of it. Nice find.</td>', 'Lovely colors and lighting. I''m not sure about the darker lump at the top - I''d find the composition a little more pleasing with a crop of it. Nice find.', '2004-05-03 15:51:00.000000', NULL, 1),
(695515, 73657, 19608, '<td valign="top">Wonderful execution.  Great colors, lines and textures.  I predict a VERY high finish for you.  Great job.<br/></td>', 'Wonderful execution.  Great colors, lines and textures.  I predict a VERY high finish for you.  Great job.', '2004-05-03 15:51:26.000000', NULL, 1),
(695516, 73947, 4008, '<td valign="top">Should have gone closer, to avoid all those edges. Would be better to just use the whole in the middle as compositional element and then the colorful structures around it, without the edges.</td>', 'Should have gone closer, to avoid all those edges. Would be better to just use the whole in the middle as compositional element and then the colorful structures around it, without the edges.', '2004-05-03 15:51:49.000000', NULL, 1),
(695517, 73929, 18080, '<td valign="top">oh... is it a ten?<br/>or a nine?<br/>Wish i could give a nine and a half as it is only the frame that i don''t like.<br/>Oh, go on then, have a ten.<br/>Well done.</td>', 'oh... is it a ten?or a nine?Wish i could give a nine and a half as it is only the frame that i don''t like.Oh, go on then, have a ten.Well done.', '2004-05-03 15:52:09.000000', NULL, 1),
(695521, 73934, 18080, '<td valign="top">beautiful shot.</td>', 'beautiful shot.', '2004-05-03 15:53:30.000000', NULL, 1),
(695522, 72580, 19608, '<td valign="top">This is so relaxing to look at - dreamy.  Great soft pastel colors, nice lines.  My only problem is the jpeg compression artifacts in the area at the top where the two orange shapes almost touch.  Overall - an exceptional image that should finish very high.</td>', 'This is so relaxing to look at - dreamy.  Great soft pastel colors, nice lines.  My only problem is the jpeg compression artifacts in the area at the top where the two orange shapes almost touch.  Overall - an exceptional image that should finish very high.', '2004-05-03 15:54:14.000000', NULL, 1),
(695524, 73886, 19608, '<td valign="top">I woulod not have expected a black and white abstract to be so effectiive - never entered my my to try it.  But you proved me wrong, this works very well indeed.  One of my favorites.  Nice job.</td>', 'I woulod not have expected a black and white abstract to be so effectiive - never entered my my to try it.  But you proved me wrong, this works very well indeed.  One of my favorites.  Nice job.', '2004-05-03 15:55:38.000000', NULL, 1),
(695525, 73214, 18080, '<td valign="top">Excelent abstract<br/>the contrast between the orange and the black is stunning... 10</td>', 'Excelent abstractthe contrast between the orange and the black is stunning... 10', '2004-05-03 15:56:23.000000', NULL, 1),
(695526, 73948, 4008, '<td valign="top">Should have gone closer to create more of an abstract out of it, avoid the edges on the right.</td>', 'Should have gone closer to create more of an abstract out of it, avoid the edges on the right.', '2004-05-03 15:56:55.000000', NULL, 1),
(695527, 73848, 19608, '<td valign="top">Nice colors and textures.  Perhaps a bit more "recognizeable" than some will like, but a very nice take on the challenge in my opinion.</td>', 'Nice colors and textures.  Perhaps a bit more "recognizeable" than some will like, but a very nice take on the challenge in my opinion.', '2004-05-03 15:57:05.000000', NULL, 1),
(695530, 73794, 4008, '<td valign="top">What a pity, why not just the great colors and lines which are on the right of the image, without the purple bit. Now I see immediately a flower, otherwise it would have been just colors and lines and structure, more of an abstract.</td>', 'What a pity, why not just the great colors and lines which are on the right of the image, without the purple bit. Now I see immediately a flower, otherwise it would have been just colors and lines and structure, more of an abstract.', '2004-05-03 15:58:57.000000', NULL, 1),
(695531, 73310, 19608, '<td valign="top">Your title works very well for the image.  Makes you wonder if it is a plate fulll of bacteria - or just a manipulated pix of a topo map.  In either case, whatever it is, it fits the challenge and has lots of interest.  I would be a bit happier if there were one "center of interest" that stood out a bit.</td>', 'Your title works very well for the image.  Makes you wonder if it is a plate fulll of bacteria - or just a manipulated pix of a topo map.  In either case, whatever it is, it fits the challenge and has lots of interest.  I would be a bit happier if there were one "center of interest" that stood out a bit.', '2004-05-03 15:59:44.000000', NULL, 1),
(695533, 73679, 19608, '<td valign="top">Wonderful lines and colors.  Should finish high.</td>', 'Wonderful lines and colors.  Should finish high.', '2004-05-03 16:00:43.000000', NULL, 1),
(695534, 73903, 4008, '<td valign="top">The top black bits are really distracting and make this less of an abstract.</td>', 'The top black bits are really distracting and make this less of an abstract.', '2004-05-03 16:01:39.000000', NULL, 1),
(695536, 73645, 15810, '<td valign="top">Brilliant 10</td>', 'Brilliant 10', '2004-05-03 16:02:51.000000', NULL, 1),
(695537, 73405, 15810, '<td valign="top">great work, beautifully framed.</td>', 'great work, beautifully framed.', '2004-05-03 16:03:46.000000', NULL, 1),
