(695541, 72801, 10047, '<td valign="top">Great colors and contrast. Really well done.</td>', 'Great colors and contrast. Really well done.', '2004-05-03 16:05:51.000000', NULL, 1),
(695542, 73747, 10047, '<td valign="top">Excellent colors and composition. Well done.</td>', 'Excellent colors and composition. Well done.', '2004-05-03 16:06:28.000000', NULL, 1),
