(695545, 73346, 10047, '<td valign="top">Excellent color and composition.</td>', 'Excellent color and composition.', '2004-05-03 16:07:50.000000', NULL, 1),
(695547, 73709, 10047, '<td valign="top">Excellent color and contrast.</td>', 'Excellent color and contrast.', '2004-05-03 16:09:03.000000', NULL, 1),
