(696111, 73996, 20324, '<td valign="top">nice compostion, but it is a lamp... it doesnt fit the theme.</td>', 'nice compostion, but it is a lamp... it doesnt fit the theme.', '2004-05-03 21:38:08.000000', NULL, 1),
