(697017, 73916, 16862, '<td valign="top">This is a good idea with a good texture but you should have cropped the overexposed white part at the bottom, It completly kills this picture</td>', 'This is a good idea with a good texture but you should have cropped the overexposed white part at the bottom, It completly kills this picture', '2004-05-04 12:20:04.000000', NULL, 1),
(697021, 73396, 16862, '<td valign="top">This is a fantastic picture, I like the colors and contrast - but the glow at the top is somehow spoiling the clearness, Still a wery cool pic   give it an 8</td>', 'This is a fantastic picture, I like the colors and contrast - but the glow at the top is somehow spoiling the clearness, Still a wery cool pic   give it an 8', '2004-05-04 12:25:51.000000', NULL, 1),
