INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(697172, 73674, 4008, '<td valign="top">very attractive colors and pattern, good abstract.</td>', 'very attractive colors and pattern, good abstract.', '2004-05-04 14:52:03.000000', NULL, 1),
(697174, 73529, 4008, '<td valign="top">I really like this one, a recognisable shape but in an environment so the total image becomes and abstract, and attractive colors and composition.</td>', 'I really like this one, a recognisable shape but in an environment so the total image becomes and abstract, and attractive colors and composition.', '2004-05-04 14:53:48.000000', NULL, 1),
(697176, 73747, 4008, '<td valign="top">I like the colors contrasted with the black. A strong shape fitting to the colors. Real good.</td>', 'I like the colors contrasted with the black. A strong shape fitting to the colors. Real good.', '2004-05-04 14:55:08.000000', NULL, 1),
(697177, 73466, 4008, '<td valign="top">just reality, not an abstract</td>', 'just reality, not an abstract', '2004-05-04 14:56:36.000000', NULL, 1),
(697186, 73888, 18709, '<td valign="top">I suppose  this is the correct definition of ''abstract''.  With all meaning abstracted.<br/>Unfortunately it doesn''t make a very interesting image.</td>', 'I suppose  this is the correct definition of ''abstract''.  With all meaning abstracted.Unfortunately it doesn''t make a very interesting image.', '2004-05-04 15:07:12.000000', NULL, 1),
(697190, 73188, 18709, '<td valign="top">Very luminous, and nice colours. Dramatic against a black background.</td>', 'Very luminous, and nice colours. Dramatic against a black background.', '2004-05-04 15:09:29.000000', NULL, 1),
(697192, 73468, 2764, '<td valign="top">ugh - border ruins it</td>', 'ugh - border ruins it', '2004-05-04 15:09:53.000000', NULL, 1),
(697193, 73929, 10705, '<td valign="top">Love the colors.  The curves and richness of the burgundy creates movement.  Nicely done ~ great title!!</td>', 'Love the colors.  The curves and richness of the burgundy creates movement.  Nicely done ~ great title!!', '2004-05-04 15:10:42.000000', NULL, 1),
(697195, 73853, 18709, '<td valign="top">Where exactly does this meeting take place?  It looks like a coal seam.</td>', 'Where exactly does this meeting take place?  It looks like a coal seam.', '2004-05-04 15:11:44.000000', NULL, 1),
(697196, 73346, 18709, '<td valign="top">Nice image, almost alive.</td>', 'Nice image, almost alive.', '2004-05-04 15:12:28.000000', NULL, 1),
(697197, 72728, 10705, '<td valign="top">Very interesting shot ... gives me an eerie feeling like I''m trapped underwater.  I also like the variations in color.</td>', 'Very interesting shot ... gives me an eerie feeling like I''m trapped underwater.  I also like the variations in color.', '2004-05-04 15:12:38.000000', NULL, 1),
(697200, 73383, 18709, '<td valign="top">Good picture, but perhaps a bit too literal to be classed as ''abstract''  ''m not complaining though.</td>', 'Good picture, but perhaps a bit too literal to be classed as ''abstract''  ''m not complaining though.', '2004-05-04 15:13:28.000000', NULL, 1),
(697202, 73802, 2764, '<td valign="top">at last!  a picture I like in this challenge - wow - 10</td>', 'at last!  a picture I like in this challenge - wow - 10', '2004-05-04 15:13:49.000000', NULL, 1),
(697203, 72750, 18709, '<td valign="top">A bit of a moonscape, but obviously on a small scale.  Nice work.</td>', 'A bit of a moonscape, but obviously on a small scale.  Nice work.', '2004-05-04 15:14:23.000000', NULL, 1),
(697204, 73943, 10705, '<td valign="top">Nice abstract.  I like the variation of colors and placement of the squares.</td>', 'Nice abstract.  I like the variation of colors and placement of the squares.', '2004-05-04 15:15:26.000000', NULL, 1),
(697206, 73785, 10705, '<td valign="top">Very cool abstract!</td>', 'Very cool abstract!', '2004-05-04 15:16:38.000000', NULL, 1),
(697208, 73534, 18709, '<td valign="top">Are you talking to me?  The answer is   "Yes"   Your photo is not as abstract as I would like to be . Still recognisable as a part of a flower.</td>', 'Are you talking to me?  The answer is   "Yes"   Your photo is not as abstract as I would like to be . Still recognisable as a part of a flower.', '2004-05-04 15:17:32.000000', NULL, 1),
(697209, 72822, 18709, '<td valign="top">Fabulous shapes and the many shades of grey are terrific.</td>', 'Fabulous shapes and the many shades of grey are terrific.', '2004-05-04 15:18:18.000000', NULL, 1),
(697214, 73537, 18709, '<td valign="top">I think this would have been more effective if you had cut out the background altogether, and just had the pole and helix.</td>', 'I think this would have been more effective if you had cut out the background altogether, and just had the pole and helix.', '2004-05-04 15:19:12.000000', NULL, 1),
(697217, 73980, 18709, '<td valign="top">Very nice light-hearted shot.  Almost like particles in a cloud chamber.</td>', 'Very nice light-hearted shot.  Almost like particles in a cloud chamber.', '2004-05-04 15:20:25.000000', NULL, 1),
(697219, 73624, 18709, '<td valign="top">Oh dear!  Somebody had a nosebleed.  Quite dramatic in a way.  The severe lines of the tiles and the chaotic shape of the other object contrast well.</td>', 'Oh dear!  Somebody had a nosebleed.  Quite dramatic in a way.  The severe lines of the tiles and the chaotic shape of the other object contrast well.', '2004-05-04 15:22:43.000000', NULL, 1),
(697221, 73113, 18709, '<td valign="top">The shapes are abstract in a way, but far too recognisable to really qualify.  I am not complaining.</td>', 'The shapes are abstract in a way, but far too recognisable to really qualify.  I am not complaining.', '2004-05-04 15:23:45.000000', NULL, 1),
(697224, 73990, 18709, '<td valign="top">Some spritzer!   I think colour would have enhanced this, but might have made it a bit too recognisable to considered abstract.</td>', 'Some spritzer!   I think colour would have enhanced this, but might have made it a bit too recognisable to considered abstract.', '2004-05-04 15:25:15.000000', NULL, 1),
(697227, 73765, 18709, '<td valign="top">This looks better than many abstract paintings of this nature that I have seen.</td>', 'This looks better than many abstract paintings of this nature that I have seen.', '2004-05-04 15:26:21.000000', NULL, 1),
(697230, 73901, 18709, '<td valign="top">This works as an abstract. It should not be recognisable as an object.  This one is a mystery to me.</td>', 'This works as an abstract. It should not be recognisable as an object.  This one is a mystery to me.', '2004-05-04 15:27:32.000000', NULL, 1),
(697233, 73727, 18709, '<td valign="top">Very graceful and ethereal.   Not STRICTLY abstract but nearly there.</td>', 'Very graceful and ethereal.   Not STRICTLY abstract but nearly there.', '2004-05-04 15:28:22.000000', NULL, 1),
(697235, 73768, 18709, '<td valign="top">These fan-blades make wonderful shapes and if you can get the light right, very<br/>telling images.  This one''s OK.</td>', 'These fan-blades make wonderful shapes and if you can get the light right, verytelling images.  This one''s OK.', '2004-05-04 15:29:24.000000', NULL, 1),
(697240, 72859, 18709, '<td valign="top">Did you crawl under the bed to get this?  I think you must have.  I like the sinuous shapes, and am quite pleased that they are not animate.</td>', 'Did you crawl under the bed to get this?  I think you must have.  I like the sinuous shapes, and am quite pleased that they are not animate.', '2004-05-04 15:31:05.000000', NULL, 1),
(697241, 73989, 18709, '<td valign="top">Well done.  Blinding colours and a childish feel, which is one aspect of abstraction.</td>', 'Well done.  Blinding colours and a childish feel, which is one aspect of abstraction.', '2004-05-04 15:32:03.000000', NULL, 1),
(697243, 72864, 18709, '<td valign="top">I think this is daylight through thick foliage.  It is very good. and exactly what the challenge is about.</td>', 'I think this is daylight through thick foliage.  It is very good. and exactly what the challenge is about.', '2004-05-04 15:33:02.000000', NULL, 1),
(697245, 72503, 18709, '<td valign="top">I can see the spiral structure but I don''t know what it is.  That is OK with ''abstracts''</td>', 'I can see the spiral structure but I don''t know what it is.  That is OK with ''abstracts''', '2004-05-04 15:34:30.000000', NULL, 1),
(697247, 73832, 18709, '<td valign="top">Very good.  I like the angle of the ray of sunshine and how it intensifies when it<br/>is horizontal.</td>', 'Very good.  I like the angle of the ray of sunshine and how it intensifies when itis horizontal.', '2004-05-04 15:35:34.000000', NULL, 1),
