(697584, 74004, 18709, '<td valign="top">Very unusual and intrigueing.   That''s how abstract images look. Good.</td>', 'Very unusual and intrigueing.   That''s how abstract images look. Good.', '2004-05-04 19:46:08.000000', NULL, 1),
