(706556, 73466, 20395, '<td valign="top">As a night landscape I would say that the image is too grainy, but you did a nice job capturing the scene. But it''s just not abstract...</td>', 'As a night landscape I would say that the image is too grainy, but you did a nice job capturing the scene. But it''s just not abstract...', '2004-05-09 05:40:27.000000', NULL, 1),
(706557, 73996, 20395, '<td valign="top">I guess my main issue with this picture is that it lacks the "wow" factor. It''s a nice composition, I like the angle, and the color is nice. it looks a little too much like an object for the challenge perhaps, but mainly it just doesn''t do much for me.</td>', 'I guess my main issue with this picture is that it lacks the "wow" factor. It''s a nice composition, I like the angle, and the color is nice. it looks a little too much like an object for the challenge perhaps, but mainly it just doesn''t do much for me.', '2004-05-09 05:43:56.000000', NULL, 1),
(706558, 73113, 20395, '<td valign="top">It''s a GREAT airplane shot- nice composition, good color. Sadly, it just doesn''t fit the challenge.</td>', 'It''s a GREAT airplane shot- nice composition, good color. Sadly, it just doesn''t fit the challenge.', '2004-05-09 05:45:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(706559, 73328, 20395, '<td valign="top">I am so impressed. I have NO idea how you did that. <br/> <br/>My highest vote of the challenge.</td>', 'I am so impressed. I have NO idea how you did that.  My highest vote of the challenge.', '2004-05-09 05:47:26.000000', NULL, 1),
(706560, 72443, 20395, '<td valign="top">My first impression was to go, "But that''s a plant that''s not... no wait, yes it is." I love the color and the focus. It''s a very beautiful shot!</td>', 'My first impression was to go, "But that''s a plant that''s not... no wait, yes it is." I love the color and the focus. It''s a very beautiful shot!', '2004-05-09 05:49:45.000000', NULL, 1),
(706561, 73953, 20395, '<td valign="top">Dig it! It''s got a weird 1950''s space age thing going on, and I like the off-center subject placement.<br/></td>', 'Dig it! It''s got a weird 1950''s space age thing going on, and I like the off-center subject placement.', '2004-05-09 05:51:31.000000', NULL, 1),
(706562, 73988, 20395, '<td valign="top">Even though it''s so simple, I find myself looking at it over and over. Very nice.</td>', 'Even though it''s so simple, I find myself looking at it over and over. Very nice.', '2004-05-09 05:52:34.000000', NULL, 1),
(706563, 73747, 20395, '<td valign="top">There might be a little too much negative space, but I love the color and the lines.</td>', 'There might be a little too much negative space, but I love the color and the lines.', '2004-05-09 05:53:26.000000', NULL, 1),
(706564, 73444, 20395, '<td valign="top">I love the color and the weird spiky thing, but the spiky bit might have gotten a little over exposed. 7</td>', 'I love the color and the weird spiky thing, but the spiky bit might have gotten a little over exposed. 7', '2004-05-09 05:54:29.000000', NULL, 1),
(706565, 72476, 20395, '<td valign="top">It almost doesn''t look like a photograph! Very interesting!<br/></td>', 'It almost doesn''t look like a photograph! Very interesting!', '2004-05-09 05:55:29.000000', NULL, 1),
(706566, 73645, 20395, '<td valign="top">I really like the color and the lines. Nice job, what is it?</td>', 'I really like the color and the lines. Nice job, what is it?', '2004-05-09 05:56:44.000000', NULL, 1),
(706567, 73405, 20395, '<td valign="top">AHHHHHHH! The torment and torture! Such a happy, colorful picture for something so evil! My mouth hurts just looking at it.</td>', 'AHHHHHHH! The torment and torture! Such a happy, colorful picture for something so evil! My mouth hurts just looking at it.', '2004-05-09 05:57:55.000000', NULL, 1),
