(706580, 72412, 11078, '<td valign="top">beautiful colour and I love the gradual tones almost look like a flame 8</td>', 'beautiful colour and I love the gradual tones almost look like a flame 8', '2004-05-09 06:39:10.000000', NULL, 1),
