(706595, 73929, 11897, '<td valign="top">excellent 10</td>', 'excellent 10', '2004-05-09 07:01:40.000000', NULL, 1),
(706596, 73798, 11897, '<td valign="top">lovely use of colour.10</td>', 'lovely use of colour.10', '2004-05-09 07:02:00.000000', NULL, 1),
(706597, 73832, 11078, '<td valign="top">nice use of shadow for abstract I like this simple but effective 7</td>', 'nice use of shadow for abstract I like this simple but effective 7', '2004-05-09 07:02:02.000000', NULL, 1),
(706599, 73403, 11897, '<td valign="top">fine photograph, but not an abstract in my opinion.</td>', 'fine photograph, but not an abstract in my opinion.', '2004-05-09 07:05:08.000000', NULL, 1),
(706600, 73927, 18722, '<td valign="top">Wonderful separation of the subject from the background.  I would have preferred a DOF just large enough to include the entire subject.</td>', 'Wonderful separation of the subject from the background.  I would have preferred a DOF just large enough to include the entire subject.', '2004-05-09 07:06:10.000000', NULL, 1),
