(708010, 73645, 11181, '<td valign="top">Wooohooo! A personal best! I''d like to thank EVERYONE who took their time to comment on my entry.</td>', 'Wooohooo! A personal best! I''d like to thank EVERYONE who took their time to comment on my entry.', '2004-05-10 01:46:45.000000', NULL, 0),
(708049, 73060, 12962, '<td valign="top">I thought this would be up in the top ten percent ... but still it''s a very fine photograph especially after I read your description ... very well planned and executed.  And at least you didn''t get a one or a two.</td>', 'I thought this would be up in the top ten percent ... but still it''s a very fine photograph especially after I read your description ... very well planned and executed.  And at least you didn''t get a one or a two.', '2004-05-10 02:00:40.000000', NULL, 0),
(708125, 73657, 10275, '<td valign="top">I was right in my prediction for a ribbon. Great photo. Congrats Henry!</td>', 'I was right in my prediction for a ribbon. Great photo. Congrats Henry!', '2004-05-10 02:28:40.000000', NULL, 0),
(708144, 72822, 12962, '<td valign="top">Wow, first entry and already in the top ten with an absolutely sensuous shot.  Hope to see more of your work!</td>', 'Wow, first entry and already in the top ten with an absolutely sensuous shot.  Hope to see more of your work!', '2004-05-10 02:41:13.000000', NULL, 0),
(708165, 73747, 2217, '<td valign="top">Thanks for all the comments and votes.  This was a fun challenge, I love abstracts and when this challenge came up I had such a fun weekend setting up props etc.  Seems it was worth it.  For those who want to know what it is - its an upside spoon in water with a waterdrop on it and the shadows come from a slotted spoon and the colors are from colored cellophane sheets behind the spoon.  I did a some burning of some unwanted reflections and a cloned some annoying specks and spots, played with hue and saturation, contrast and brightness, added a border and ran it through neat image.<br/><br/><i>Message edited by author 2004-05-11 02:59:27.</i></td>', 'Thanks for all the comments and votes.  This was a fun challenge, I love abstracts and when this challenge came up I had such a fun weekend setting up props etc.  Seems it was worth it.  For those who want to know what it is - its an upside spoon in water with a waterdrop on it and the shadows come from a slotted spoon and the colors are from colored cellophane sheets behind the spoon.  I did a some burning of some unwanted reflections and a cloned some annoying specks and spots, played with hue and saturation, contrast and brightness, added a border and ran it through neat image.', '2004-05-10 02:51:37.000000', '2004-05-11 03:59:27.000000', 0),
(708207, 73346, 19668, '<td valign="top">Congrats on making it to the top Nikon D70 picture page.<br/><a href="//www.dpchallenge.com/camera.php?CAMERA_ID=767" rel="nofollow" target="_blank">//www.dpchallenge.com/camera.php?CAMERA_ID=767</a> <br/>Well done!</td>', 'Congrats on making it to the top Nikon D70 picture page.//www.dpchallenge.com/camera.php?CAMERA_ID=767 Well done!', '2004-05-10 03:19:16.000000', NULL, 0),
(708219, 73657, 19668, '<td valign="top">Great picture! Congrats. Got a +10 from me.</td>', 'Great picture! Congrats. Got a +10 from me.', '2004-05-10 03:24:01.000000', NULL, 0),
(708238, 73747, 3765, '<td valign="top">Well done Jean, you are at it again.</td>', 'Well done Jean, you are at it again.', '2004-05-10 03:32:46.000000', NULL, 0),
